#include <fstream>
#include <limits>
#include <vector>
using namespace std;
struct Fence { int x, y; char slope; };
void solve(istream& in, ostream& out) {
    int n, a, b; in >> n >> a >> b;
    vector<Fence> fences(n);
    for (Fence& f : fences) in >> f.x >> f.y >> f.slope;
    const int slash[4] = {1, 0, 3, 2};
    const int backslash[4] = {3, 2, 1, 0};
    // Headings: east, north, west, south.
    auto reaches = [&](int toggled) {
        if (a == 0 && b == 0) return true;
        int x = 0, y = 0, direction = 0;
        vector<unsigned char> seen(4 * n, 0);
        while (true) {
            int next = -1;
            long long closest = numeric_limits<long long>::max();
            for (int i = 0; i <= n; ++i) {
                int px = i == n ? a : fences[i].x;
                int py = i == n ? b : fences[i].y;
                long long dx = (long long)px - x, dy = (long long)py - y;
                long long distance = -1;
                if (direction == 0 && dy == 0 && dx > 0) distance = dx;
                if (direction == 1 && dx == 0 && dy > 0) distance = dy;
                if (direction == 2 && dy == 0 && dx < 0) distance = -dx;
                if (direction == 3 && dx == 0 && dy < 0) distance = -dy;
                if (distance > 0 && distance < closest) {
                    closest = distance; next = i;
                }
            }
            if (next == -1) return false;
            if (next == n) return true;
            int state = 4 * next + direction;
            if (seen[state]) return false;
            seen[state] = 1;
            bool isSlash = fences[next].slope == '/';
            if (next == toggled) isSlash = !isSlash;
            x = fences[next].x; y = fences[next].y;
            direction = isSlash ? slash[direction] : backslash[direction];
        }
    };
    if (reaches(-1)) { out << 0 << '\n'; return; }
    for (int i = 0; i < n; ++i) {
        if (reaches(i)) { out << i + 1 << '\n'; return; }
    }
    out << -1 << '\n';
}
int main() {
    ifstream in("mirrors.in"); ofstream out("mirrors.out");
    solve(in, out);
    return 0;
}
