#include <algorithm>
#include <fstream>
#include <utility>
#include <vector>
using namespace std;
void solve(istream& in, ostream& out) {
    int n; in >> n;
    vector<pair<long long, int> > events;
    events.reserve(2 * n);
    long long position = 0;
    for (int i = 0; i < n; ++i) {
        long long distance; char direction; in >> distance >> direction;
        long long next = position + (direction == 'R' ? distance : -distance);
        events.push_back(make_pair(min(position, next), 1));
        events.push_back(make_pair(max(position, next), -1));
        position = next;
    }
    sort(events.begin(), events.end());
    long long previous = events[0].first, answer = 0;
    int coats = 0;
    for (size_t i = 0; i < events.size();) {
        long long coordinate = events[i].first;
        if (coats >= 2) answer += coordinate - previous;
        int change = 0;
        while (i < events.size() && events[i].first == coordinate) {
            change += events[i].second; ++i;
        }
        coats += change;
        previous = coordinate;
    }
    out << answer << '\n';
}
int main() {
    ifstream in("paint.in"); ofstream out("paint.out");
    solve(in, out);
    return 0;
}
