#include <fstream>
#include <numeric>
#include <vector>
using namespace std;
struct Statement { int x, y, different; };
struct ParityGroups {
    vector<int> parent, size, parity;
    explicit ParityGroups(int n) : parent(n + 1), size(n + 1, 1), parity(n + 1, 0) {
        iota(parent.begin(), parent.end(), 0);
    }
    int root(int x) {
        if (parent[x] == x) return x;
        int oldParent = parent[x];
        parent[x] = root(oldParent);
        parity[x] ^= parity[oldParent];
        return parent[x];
    }
    bool add(int x, int y, int different) {
        int a = root(x), b = root(y);
        int required = parity[x] ^ parity[y] ^ different;
        if (a == b) return required == 0;
        if (size[a] > size[b]) { int temp = a; a = b; b = temp; }
        parent[a] = b;
        parity[a] = required;
        size[b] += size[a];
        return true;
    }
};
void solve(istream& in, ostream& out) {
    int n, m; in >> n >> m;
    vector<Statement> statements(m);
    for (Statement& s : statements) {
        char claim; in >> s.x >> s.y >> claim;
        s.different = claim == 'L';
    }
    ParityGroups groups(n);
    for (int i = 0; i < m; ++i) {
        const Statement& s = statements[i];
        if (!groups.add(s.x, s.y, s.different)) {
            out << i << '\n'; return;
        }
    }
    out << m << '\n';
}
int main() {
    ifstream in("truth.in"); ofstream out("truth.out");
    solve(in, out);
    return 0;
}
